"""Approved chapter placements, captions and source boundaries.

Used by integration/verification tools and the local gallery. Sections identify
existing chapter headings; the prose/equations around them are preserved.
"""

from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
CHAPTERS = sorted((ROOT / "book/chapters").glob("[0-9][0-9]-*.md"))


def entry(name, chapter, section, caption, question, notebook, candidate, reuse=None, poster=None):
    return {"id": name, "chapter": str(CHAPTERS[chapter - 1].relative_to(ROOT)),
            "section": section, "gif": reuse or f"visuals/chapters/rendered/{name}.gif",
            "poster": poster or f"visuals/chapters/rendered/{name}.png",
            "mode": "retain" if name == "bpe-byte-merges" else "reuse" if reuse else "new",
            "caption": caption, "question": question, "notebook": f"notebooks/{notebook}.ipynb",
            "candidate": candidate}


